const toggle=document.getElementById('ea-toggle'),drawer=document.getElementById('ea-drawer');if(toggle&&drawer){const reconcile=()=>{const narrow=matchMedia('(max-width:900px)').matches,visible=!narrow||document.body.classList.contains('ea-open');drawer.setAttribute('aria-hidden',String(!visible));toggle.setAttribute('aria-expanded',String(visible));if('inert' in drawer)drawer.inert=!visible};new MutationObserver(reconcile).observe(document.body,{attributes:true,attributeFilter:['class']});addEventListener('resize',reconcile,{passive:true});reconcile()}
