/* Consistent responsive navigation and keyboard access.
   A single, shared menu serves every route; local content controls remain intact. */
(()=>{'use strict';
const init=()=>{
 const drawer=document.getElementById('ea-drawer'),toggle=document.getElementById('ea-toggle');
 if(!drawer||!toggle)return;
 drawer.setAttribute('aria-label','Primary Eastern Axis navigation');

 const region=document.getElementById('region-filter');
 if(region&&!region.getAttribute('aria-label')&&!region.labels?.length)region.setAttribute('aria-label','Filter countries by world region');
 const mapButtons=()=>{
 document.querySelectorAll('svg.world-svg').forEach(svg=>{if(svg.querySelector('.country[tabindex]'))svg.setAttribute('role','group')});
 document.querySelectorAll('svg .country[tabindex]').forEach(path=>{
   path.setAttribute('role','button');
   path.setAttribute('aria-pressed',String(path.classList.contains('selected')));
 });
 };
 mapButtons();addEventListener('ea-country-picked',mapButtons);
 const search=document.getElementById('ea-search'),field=document.getElementById('ea-search-input');
 if(search&&field&&!search.querySelector('label[for="ea-search-input"]')){
   const label=document.createElement('label');label.htmlFor='ea-search-input';label.className='ea-search-label';label.textContent='Find a country';search.insertBefore(label,field);
 }
 // Local page headers formerly repeated the command-center links; keep page-specific tabs.
 document.querySelectorAll('body.ea-sub header nav').forEach(nav=>{
   const a=[...nav.querySelectorAll('a[href]')];
   const global=a.filter(el=>{
     const u=new URL(el.href,location.href);
     return (u.origin===location.origin||u.origin==='https://eastern-axis-resources-power.vercel.app')&&/^\/(?:$|risk\/|resources\/|collection\/|declassified\/|cross-border\/|global-influence\/|power-influence\/)/.test(u.pathname);
   });
   if(a.length>=2&&global.length===a.length){nav.hidden=true;nav.setAttribute('aria-hidden','true')}
 });
 let locked=[],opened=false,returnFocus=null;
 const small=()=>matchMedia('(max-width:900px)').matches;
 const navFocusable=()=>[toggle,...drawer.querySelectorAll('a[href],button:not([disabled]),input:not([disabled]),summary,[tabindex]:not([tabindex="-1"])')].filter(el=>{
   return el.getClientRects().length>0&&!el.closest('[hidden]')&&!el.closest('[inert]');
 });
 function sync(){
   const on=small()&&document.body.classList.contains('ea-open');
   toggle.setAttribute('aria-label',on?'Close Menu':'Open Menu');
   toggle.setAttribute('aria-expanded',String(on));
   drawer.setAttribute('aria-hidden',String(small()&&!on));
   drawer.inert=small()&&!on;
   if(on&&!opened){
      opened=true;returnFocus=document.activeElement;locked=[];
      for(const el of [...document.body.children]){
        if(el===drawer||el.id==='ea-appbar'||el.id==='ea-backdrop'||el.tagName==='SCRIPT'||el.tagName==='STYLE')continue;
        locked.push([el,el.inert]);el.inert=true;
      }
   }else if(!on&&opened){
      opened=false;
      for(const [el,was] of locked){if(el.isConnected)el.inert=was}locked=[];
      if(drawer.contains(document.activeElement)&&returnFocus?.isConnected){
        returnFocus.focus({preventScroll:true});
      }
   }
 }
 document.addEventListener('keydown',e=>{
   if(e.key!=='Tab'||!small()||!document.body.classList.contains('ea-open'))return;
   const els=navFocusable();if(!els.length)return;
   const first=els[0],last=els[els.length-1],active=document.activeElement;
   if(!els.includes(active)){e.preventDefault();first.focus();return}
   if(e.shiftKey&&active===first){e.preventDefault();last.focus()}
   else if(!e.shiftKey&&active===last){e.preventDefault();first.focus()}
 },true);
 drawer.addEventListener('click',e=>{
   const a=e.target.closest('a[href]');if(!a)return;
   const u=new URL(a.href,location.href);
   if(location.pathname==='/'&&u.pathname==='/'&&u.hash&&u.origin===location.origin){
     setTimeout(()=>{
       const heading=document.querySelector('.view.active h1');
       if(heading){heading.tabIndex=-1;heading.focus({preventScroll:true})}
     },0);
   }
 });
 new MutationObserver(sync).observe(document.body,{attributes:true,attributeFilter:['class']});
 addEventListener('resize',sync,{passive:true});sync();
};
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();
})();


/* Risk section follows the WAI-ARIA tab pattern, including keyboard navigation. */
(()=>{'use strict';const init=()=>{
 const root=document.querySelector('body.ea-sub [role="tablist"]');
 if(!root||!location.pathname.startsWith('/risk/'))return;
 const tabs=[...root.querySelectorAll('button[data-tab]')];
 if(!tabs.length)return;
 root.setAttribute('aria-label','Risk intelligence categories');
 for(const tab of tabs){
   const key=tab.dataset.tab;
   const panel=document.getElementById('risk-'+key);
   tab.id=tab.id||'ea-risk-tab-'+key;tab.setAttribute('role','tab');
   if(panel){tab.setAttribute('aria-controls',panel.id);panel.setAttribute('role','tabpanel');panel.setAttribute('aria-labelledby',tab.id)}
 }
 const sync=()=>{for(const tab of tabs){const active=tab.classList.contains('active');tab.setAttribute('aria-selected',String(active));tab.tabIndex=active?0:-1;
   const panel=document.getElementById('risk-'+tab.dataset.tab);
   if(panel)panel.hidden=!active;
 }};
 root.addEventListener('keydown',e=>{
   const i=tabs.indexOf(document.activeElement);
   if(i<0)return;
   let j=i;
   if(e.key==='ArrowRight')j=(i+1)%tabs.length;
   else if(e.key==='ArrowLeft')j=(i+tabs.length-1)%tabs.length;
   else if(e.key==='Home')j=0;
   else if(e.key==='End')j=tabs.length-1;
   else return;
   e.preventDefault();tabs[j].focus();tabs[j].click();
 });
 new MutationObserver(sync).observe(root,{attributes:true,attributeFilter:['class'],subtree:true});
 sync();
 };if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init()})();
/* Distinguish the archive's light header from dark-nav colors. */
(()=>{'use strict';if(!location.pathname.startsWith('/declassified/'))return;const run=()=>document.body.classList.add('ea-declassified-a11y');if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',run,{once:true});else run()})();
